function toCount(value) {
  const n = Math.trunc(Number(value));
  return Number.isFinite(n) && n > 0 ? n : 0;
}

function isExpired(order, now) {
  if (!order || order.estado !== 'PENDIENTE_RECETA') return false;
  const raw = order.fecha_expiracion;
  if (raw === null || raw === undefined || raw === '') return false;
  const expiresAt = new Date(raw);
  if (Number.isNaN(expiresAt.getTime())) return false;
  const reference = now instanceof Date ? now : new Date(now);
  if (Number.isNaN(reference.getTime())) return false;
  return expiresAt.getTime() <= reference.getTime();
}

function selectExpiredOrders(orders, now) {
  const source = Array.isArray(orders) ? orders : [];
  return source.filter((order) => isExpired(order, now));
}

function findInventoryRow(inventoryRows, medicamentoId) {
  const source = Array.isArray(inventoryRows) ? inventoryRows : [];
  const key = String(medicamentoId);
  return source.find((row) => row && String(row.medicamento_id) === key) || null;
}

function currentReserved(inventoryRows, medicamentoId) {
  const row = findInventoryRow(inventoryRows, medicamentoId);
  return row ? Math.max(0, toCount(row.stock_reservado)) : 0;
}

function aggregateInventoryUpdates(expiredOrders, inventoryRows, now) {
  const nowIso = (now instanceof Date ? now : new Date(now)).toISOString();
  const totals = new Map();
  (expiredOrders || []).forEach((order) => {
    const key = String(order.medicamento_id);
    totals.set(key, (totals.get(key) || 0) + toCount(order.cantidad));
  });
  const updates = [];
  totals.forEach((totalCantidad, key) => {
    const row = findInventoryRow(inventoryRows, key);
    if (!row) return;
    const current = Math.max(0, toCount(row.stock_reservado));
    const newReserved = Math.max(0, current - totalCantidad);
    updates.push({
      medicamento_id: row.medicamento_id,
      stock_reservado: newReserved,
      delta_reservado: newReserved - current,
      clamped: totalCantidad > current,
      ultima_actualizacion: nowIso,
    });
  });
  return updates;
}

function distributeReleases(expiredOrders, inventoryRows) {
  const releasedSoFar = new Map();
  return (expiredOrders || []).map((order) => {
    const key = String(order.medicamento_id);
    const reserved = currentReserved(inventoryRows, key);
    const wanted = toCount(order.cantidad);
    const already = releasedSoFar.get(key) || 0;
    const left = Math.max(0, reserved - already);
    const released = Math.min(wanted, left);
    releasedSoFar.set(key, already + released);
    return { released: released, clamped: released < wanted };
  });
}

function buildBitacoraRows(expiredOrders, inventoryRows, now) {
  const nowIso = (now instanceof Date ? now : new Date(now)).toISOString();
  const plan = distributeReleases(expiredOrders, inventoryRows);
  return (expiredOrders || []).map((order, index) => {
    const entry = plan[index];
    let detalle =
      'Expiracion 12h: liberadas ' +
      entry.released +
      ' de ' +
      toCount(order.cantidad) +
      ' unidades reservadas';
    if (entry.clamped) detalle += '; CLAMP: stock_reservado insuficiente';
    return {
      timestamp: nowIso,
      accion: 'EXPIRACION',
      codigo_far: order.codigo_far,
      medicamento_id: order.medicamento_id,
      delta_reservado: -entry.released,
      detalle: detalle,
    };
  });
}

function buildExpiryMessage(order, released, catalogRow) {
  const code = order && order.codigo_far ? String(order.codigo_far) : '';
  let message =
    'Tu pedido #' +
    code +
    ' fue cancelado por falta de receta después de 12 horas.';
  if (catalogRow && catalogRow.nombre_comercial) {
    message +=
      ' Liberamos ' +
      released +
      ' unidades de ' +
      catalogRow.nombre_comercial +
      ' al stock.';
  }
  return message;
}

function buildNotifications(expiredOrders, inventoryRows, catalogRows) {
  const plan = distributeReleases(expiredOrders, inventoryRows);
  const source = Array.isArray(catalogRows) ? catalogRows : [];
  return (expiredOrders || []).map((order, index) => {
    const key = String(order.medicamento_id);
    const catalogRow =
      source.find((row) => row && String(row.medicamento_id) === key) || null;
    return {
      phone: order.telefono,
      message: buildExpiryMessage(order, plan[index].released, catalogRow),
    };
  });
}

function buildExpiryPlan(expiredOrders, inventoryRows, catalogRows, now) {
  return {
    inventoryUpdates: aggregateInventoryUpdates(expiredOrders, inventoryRows, now),
    bitacoraRows: buildBitacoraRows(expiredOrders, inventoryRows, now),
    notifications: buildNotifications(expiredOrders, inventoryRows, catalogRows),
  };
}

// --- n8n data assembly -------------------------------------------------------
// Guarded: outside the editor (test harness) `$` does not exist, so this block
// stays inert and only the named functions above are reachable.
if (typeof $ !== 'undefined') {
  const now = new Date();
  const ordenes = $('read_ordenes').all().map((item) => item.json);
  const inventario = $('read_inventario').all().map((item) => item.json);
  const catalogo = $('read_catalogo').all().map((item) => item.json);
  const expired = selectExpiredOrders(ordenes, now);
  const plan = buildExpiryPlan(expired, inventario, catalogo, now);
  return [
    {
      json: {
        count: expired.length,
        expired: expired,
        inventoryUpdates: plan.inventoryUpdates,
        bitacoraRows: plan.bitacoraRows,
        notifications: plan.notifications,
      },
    },
  ];
}

const expired = $('find_expired').item.json.expired || [];
return expired.map((order) => ({
  json: Object.assign({}, order, {
    estado: 'CANCELADO_EXPIRADO',
    fecha_expiracion: '',
  }),
}));

const notifications = $('find_expired').item.json.notifications || [];
return notifications.map((entry) => ({
  json: { phone: entry.phone, message: entry.message },
}));
